-- Phase 2F: hashed storage for activation and admin-invitation tokens.
--
-- Goal: a read of these tables must not yield usable credentials. New tokens
-- are generated by the server, shown once, and only their SHA-256 is stored.
--
-- TRANSITION (no existing invitation is invalidated, nothing is revealed):
--   * token_hash is added and BACKFILLED inside the database from existing raw
--     tokens, so outstanding links keep working.
--   * Lookups accept either the hash of the presented token or, for legacy
--     rows only, the raw value. Same function names/signatures as before, so
--     currently deployed edge functions keep working.
--   * The legacy raw `token` columns are NOT cleared here. After the new edge
--     functions are deployed and the longest legacy lifetime has passed
--     (activation 24h, admin 72h) an operator runs the cleanup documented in
--     docs/engineering/REGISTRATION_COMMS_PHASE_2F_REMEDIATION.md
--     (UPDATE ... SET token = NULL), then a later migration drops the column.
--   * tenant_invitations / landlord_invitations are NOT changed here (their
--     validation RPCs need a separate, reviewed change); see the report.
--
-- Also fixes the activation-token permission boundary:
--   * validate_activation_token and use_activation_token are service_role only
--     (previously validate was callable by anon/authenticated, disclosing the
--     account email for any presented token).
--   * consume_activation_token() atomically marks the token used AND returns
--     the account it belongs to, so a token cannot be consumed by one request
--     and applied to a different account.
--
-- Idempotent. Do NOT apply to any environment until the Phase 2D migration
-- reconciliation has been completed and approved.

-- ── account_activations ──────────────────────────────────────────
ALTER TABLE public.account_activations ADD COLUMN IF NOT EXISTS token_hash text;
ALTER TABLE public.account_activations ALTER COLUMN token DROP NOT NULL;

UPDATE public.account_activations
   SET token_hash = encode(extensions.digest(token, 'sha256'), 'hex')
 WHERE token IS NOT NULL AND token_hash IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS account_activations_token_hash_key
  ON public.account_activations (token_hash) WHERE token_hash IS NOT NULL;

-- Rows still created by older code through the legacy column default get a hash too.
CREATE OR REPLACE FUNCTION public.account_activations_set_token_hash()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
BEGIN
  IF NEW.token IS NOT NULL AND NEW.token_hash IS NULL THEN
    NEW.token_hash := encode(extensions.digest(NEW.token, 'sha256'), 'hex');
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS trg_account_activations_token_hash ON public.account_activations;
CREATE TRIGGER trg_account_activations_token_hash
  BEFORE INSERT OR UPDATE OF token ON public.account_activations
  FOR EACH ROW EXECUTE FUNCTION public.account_activations_set_token_hash();

-- Issue a new activation: only the hash is stored; the raw token is returned once.
-- Earlier unused activations for the user are revoked (safe resend).
CREATE OR REPLACE FUNCTION public.issue_account_activation(p_user_id uuid, p_ttl_hours integer DEFAULT 24)
RETURNS TABLE (token text, expires_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_token text := encode(extensions.gen_random_bytes(32), 'hex');
  v_ttl integer := LEAST(GREATEST(COALESCE(p_ttl_hours, 24), 1), 168);
  v_expires timestamptz := now() + make_interval(hours => v_ttl);
BEGIN
  UPDATE public.account_activations aa SET used_at = now()
   WHERE aa.user_id = p_user_id AND aa.used_at IS NULL;
  INSERT INTO public.account_activations (user_id, token, token_hash, expires_at)
  VALUES (p_user_id, NULL, encode(extensions.digest(v_token, 'sha256'), 'hex'), v_expires);
  token := v_token;
  expires_at := v_expires;
  RETURN NEXT;
END $$;

CREATE OR REPLACE FUNCTION public.validate_activation_token(token_value text)
RETURNS TABLE (user_id uuid, email text)
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path = public
AS $$
DECLARE v_hash text;
BEGIN
  IF token_value IS NULL OR length(token_value) < 32 OR length(token_value) > 256 THEN RETURN; END IF;
  v_hash := encode(extensions.digest(token_value, 'sha256'), 'hex');
  RETURN QUERY
  SELECT aa.user_id, u.email::text
    FROM public.account_activations aa
    JOIN auth.users u ON u.id = aa.user_id
   WHERE (aa.token_hash = v_hash OR (aa.token_hash IS NULL AND aa.token = token_value))
     AND aa.used_at IS NULL AND aa.expires_at > now();
END $$;

CREATE OR REPLACE FUNCTION public.use_activation_token(token_value text)
RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE v_hash text; v_used boolean;
BEGIN
  IF token_value IS NULL OR length(token_value) < 32 OR length(token_value) > 256 THEN RETURN false; END IF;
  v_hash := encode(extensions.digest(token_value, 'sha256'), 'hex');
  UPDATE public.account_activations
     SET used_at = now()
   WHERE (token_hash = v_hash OR (token_hash IS NULL AND token = token_value))
     AND used_at IS NULL AND expires_at > now()
  RETURNING true INTO v_used;
  RETURN COALESCE(v_used, false);
END $$;

-- Atomic consume: the same statement that burns the token returns its owner.
CREATE OR REPLACE FUNCTION public.consume_activation_token(token_value text)
RETURNS TABLE (user_id uuid, email text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE v_hash text;
BEGIN
  IF token_value IS NULL OR length(token_value) < 32 OR length(token_value) > 256 THEN RETURN; END IF;
  v_hash := encode(extensions.digest(token_value, 'sha256'), 'hex');
  RETURN QUERY
  WITH used AS (
    UPDATE public.account_activations aa
       SET used_at = now()
     WHERE (aa.token_hash = v_hash OR (aa.token_hash IS NULL AND aa.token = token_value))
       AND aa.used_at IS NULL AND aa.expires_at > now()
    RETURNING aa.user_id
  )
  SELECT used.user_id, u.email::text FROM used JOIN auth.users u ON u.id = used.user_id;
END $$;

REVOKE ALL ON FUNCTION public.issue_account_activation(uuid, integer) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.validate_activation_token(text) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.use_activation_token(text) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.consume_activation_token(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.issue_account_activation(uuid, integer) TO service_role;
GRANT EXECUTE ON FUNCTION public.validate_activation_token(text) TO service_role;
GRANT EXECUTE ON FUNCTION public.use_activation_token(text) TO service_role;
GRANT EXECUTE ON FUNCTION public.consume_activation_token(text) TO service_role;

-- ── admin_invitations ────────────────────────────────────────────
ALTER TABLE public.admin_invitations ADD COLUMN IF NOT EXISTS token_hash text;
ALTER TABLE public.admin_invitations ALTER COLUMN token DROP NOT NULL;

UPDATE public.admin_invitations
   SET token_hash = encode(extensions.digest(token, 'sha256'), 'hex')
 WHERE token IS NOT NULL AND token_hash IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS admin_invitations_token_hash_key
  ON public.admin_invitations (token_hash) WHERE token_hash IS NOT NULL;

CREATE OR REPLACE FUNCTION public.admin_invitations_set_token_hash()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
BEGIN
  IF NEW.token IS NOT NULL AND NEW.token_hash IS NULL THEN
    NEW.token_hash := encode(extensions.digest(NEW.token, 'sha256'), 'hex');
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS trg_admin_invitations_token_hash ON public.admin_invitations;
CREATE TRIGGER trg_admin_invitations_token_hash
  BEFORE INSERT OR UPDATE OF token ON public.admin_invitations
  FOR EACH ROW EXECUTE FUNCTION public.admin_invitations_set_token_hash();
